package org.json; import java.util.*; public class JSONObject { final Map<String,Object> m=new HashMap<>(); public JSONObject put(String k,Object v){m.put(k,v);return this;} public String getString(String k){return (String)m.get(k);} public long getLong(String k){return ((Number)m.get(k)).longValue();} public int getInt(String k){return ((Number)m.get(k)).intValue();} public JSONObject getJSONObject(String k){return (JSONObject)m.get(k);} public JSONArray getJSONArray(String k){return (JSONArray)m.get(k);} public boolean optBoolean(String k,boolean d){return m.containsKey(k)?(Boolean)m.get(k):d;} }